const menu=document.querySelector('.menu');const nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Đóng menu':'Mở menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Mở menu')}));
const products={villa:{title:'Biệt thự',tag:'KHÔNG GIAN RIÊNG TƯ',description:'Dành không gian cho những điều quan trọng: gia đình, sự riêng tư và cách sống của riêng bạn.',type:'Đơn lập & song lập',label:'PHỐI CẢNH THAM KHẢO'},townhouse:{title:'Nhà liền kề',tag:'NHỊP SỐNG KẾT NỐI',description:'Một gợi mở cho gia đình muốn tìm hiểu nhà ở thấp tầng với công năng phù hợp cho sinh hoạt hằng ngày.',type:'Nhà liền kề',label:'ẢNH TỪ NGUỒN THAM KHẢO'},shop:{title:'Shophouse',tag:'KHÔNG GIAN ĐA CÔNG NĂNG',description:'Khám phá loại hình nhà phố thương mại. Trao đổi kỹ về vị trí từng căn, công năng và điều kiện sử dụng trước khi lựa chọn.',type:'Nhà phố thương mại',label:'PHỐI CẢNH THAM KHẢO'}};
const tabs=[...document.querySelectorAll('[data-product]')];function selectProduct(tab){const key=tab.dataset.product,p=products[key];tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});document.querySelector('#product-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#product-title').textContent=p.title;document.querySelector('#product-description').textContent=p.description;document.querySelector('#product-tag').textContent=p.tag;document.querySelector('#product-type').textContent=p.type;document.querySelector('#product-label').textContent=p.label;const img=document.querySelector('#product-image');img.src=`assets/${key}.jpg`;img.alt=`${p.label==='PHỐI CẢNH THAM KHẢO'?'Phối cảnh':'Hình ảnh'} ${p.title} Anlac Green Symphony`;document.querySelector('#product-cta').innerHTML=`Tìm hiểu ${p.title.toLowerCase()} <span>↗</span>`;document.querySelector('[name=property]').value=p.title}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectProduct(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();selectProduct(tabs[n]);tabs[n].focus()}})});
const imageDialog=document.querySelector('#image-dialog');document.querySelectorAll('.zoom-image').forEach(button=>button.addEventListener('click',()=>{imageDialog.querySelector('img').src=button.dataset.image;imageDialog.querySelector('img').alt=button.dataset.caption;imageDialog.querySelector('p').textContent=button.dataset.caption;imageDialog.showModal()}));document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});document.querySelector('#privacy-button').addEventListener('click',()=>document.querySelector('#privacy-dialog').showModal());
let inquiry='';document.querySelector('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);inquiry=`Kính gửi bộ phận tư vấn Anlac Green Symphony,\n\nTôi muốn tìm hiểu dự án.\nHọ tên: ${String(data.get('name')).trim()}\nĐiện thoại: ${String(data.get('phone')).trim()}\nLoại hình: ${data.get('property')}\nNhu cầu: ${String(data.get('message')).trim()||'Mong được tư vấn thêm.'}\n\nVui lòng phản hồi thông tin và đề xuất bước tiếp theo phù hợp. Xin cảm ơn.`;document.querySelector('#form-result').hidden=false;document.querySelector('#copy-status').textContent='';window.location.href=`mailto:info@anlac.vn?subject=${encodeURIComponent('Yêu cầu tư vấn Anlac Green Symphony')}&body=${encodeURIComponent(inquiry)}`});document.querySelector('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(inquiry);document.querySelector('#copy-status').textContent='Đã sao chép. Dán nội dung vào email gửi info@anlac.vn.'}catch{const area=document.createElement('textarea');area.value=inquiry;area.readOnly=true;document.querySelector('#form-result').append(area);area.focus();area.select();document.querySelector('#copy-status').textContent='Hãy sao chép nội dung trong ô và gửi tới info@anlac.vn.'}});
